mapper.select:
SELECT delivery_id, request_id, address_vault_token, locale, parameters,
        status, attempt_count, next_retry_time, version, create_time, update_time FROM t_notification_delivery WHERE
        delivery_id = #{id}

mapper.update:
UPDATE t_notification_delivery SET status = #{status}, attempt_count = #{attemptCount},
next_retry_time = #{nextRetryTime}, version = version + 1, update_time = #{now}
WHERE delivery_id = #{item.deliveryId} AND version = #{item.version} AND status = #{item.status}
